css:
.print-heading {
  text-align: center;
  margin-bottom: 30px;
}

.print-heading h1 {
  margin: 0 0 4px;
  font-size: 15pt;
  font-weight: 700;
}

.print-heading p {
  margin: 4px 0 0;
}

/* Signature block */
.signatures {
  margin-top: 24px;
  page-break-inside: auto;
}

.signatures table {
  width: 100%;
  border-collapse: collapse;
  table-layout: fixed;
}

.signatures tr {
  page-break-inside: avoid;
}

.signatures td {
  border: none;
  vertical-align: bottom;
}

.signatures .signature-cell {
  width: 68%;
  padding: 30px 30px 12px 0;
}

.signatures .date-cell {
  width: 32%;
  padding: 30px 0 12px 20px;
}

.signatures .signature-line {
  min-height: 18px;
  border-bottom: 1px solid #333;
}

.signatures .signature-label {
  margin-top: 5px;
  font-size: 9pt;
}

@page {
  @bottom-right {
    content: "Page " counter(page) " of " counter(pages);
    font-size: 10pt;
    color: #999;
  }
}

/* Case details block: plain labelled facts above Introduction, not numbered */
.case-details {
  margin: 0 0 20px;
  font-size: 10.5pt;
}

.case-details__row {
  display: table;
  width: 100%;
  margin-bottom: 3px;
}

.case-details__label {
  display: table-cell;
  width: 140px;
  font-weight: 700;
  vertical-align: top;
}

.case-details__value {
  display: table-cell;
  vertical-align: top;
}

/* Outcome body: numbered paragraphs + evidence footnotes */
.outcome-body h4 {
  margin: 20px 0 8px;
  font-size: 12pt;
  font-weight: 700;
}

.numbered-para {
  display: table;
  width: 100%;
  margin: 0 0 10px;
}

.para-number {
  display: table-cell;
  padding-right: 8px;
  white-space: nowrap;
  vertical-align: top;
  font-weight: 400;
}

.para-text {
  display: table-cell;
  width: 100%;
  text-align: justify;
  vertical-align: top;
}

.para-text ol,
.para-text ul {
  text-align: left;
  margin: 6px 0 6px 1.5em;
}

.numbered-para.level-1 {
  margin-left: 2em;
}

.numbered-para.level-2 {
  margin-left: 4em;
}

.numbered-para.level-3 {
  margin-left: 6em;
}

sup.footnote-ref {
  font-weight: 700;
  color: #333;
}

.footnotes-section {
  margin-top: 24px;
  border-top: 1px solid #ccc;
  padding-top: 10px;
  page-break-inside: avoid;
}

.footnotes-section h4 {
  margin: 0 0 8px;
  font-size: 11pt;
}

.footnotes-list {
  font-size: 9pt;
  padding-left: 18px;
  margin: 0;
}

.footnotes-list li {
  margin-bottom: 4px;
}

@page {
  @bottom-right {
    content: "Page " counter(page) " of " counter(pages);
    font-size: 10pt;
    color: #999;
  }
}
